import {coaching} from './coaching.js';
import{MISSION_LENGTH,DURATION,STARTING_CREDITS,points,agents,questionBank,createGame,startGame,remaining,finish,choose,next,score}from'./engine.js';
const root=document.querySelector('#app');let state=createGame();
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=()=>{const s=remaining(state,Date.now());return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
function team(){return agents.filter(a=>state.team.includes(a.id));}
function brief(){return `<aside class="side"><div class="brief-label"><span class="eyebrow">Your mission</span><span class="tag">LAUNCH READINESS</span></div><div class="mission-art" aria-hidden="true"><span class="node">⌕</span><span class="connector"></span><span class="node">◇</span><span class="connector"></span><span class="node">✓</span></div><h2>Friday launch.<br>One reliable report.</h2><p>Turn engineering tickets, test results, and team updates into a launch-readiness recommendation.</p><div class="objective"><strong>The goal</strong><p>Surface the blockers. Back up every claim. Keep the right person in control.</p></div><div class="brief-stats"><div><strong class="mono">${String(DURATION/60).padStart(2,'0')}:00</strong><span>Time to make your calls</span></div><div><strong class="mono">${STARTING_CREDITS}</strong><span>Starting credits</span></div></div></aside>`;}
function setup(){const cost=team().reduce((sum,a)=>sum+a.cost,0);root.innerHTML=`<div class="game-layout entry"><section><span class="pill">A ${DURATION/60}-minute challenge</span><div class="intro"><h1>Good agents.<br>Great judgment.</h1><p class="muted">Build your AI team. Handle the unexpected.<br>Get your launch report over the line.</p></div><div class="section-head"><h3>Pick your 3 teammates</h3><span class="muted mono">${state.team.length} / 3 selected</span></div><div class="cards">${agents.map(a=>`<button class="agent" data-agent="${a.id}" aria-pressed="${state.team.includes(a.id)}"><span class="agent-top"><span class="agent-icon" aria-hidden="true">${a.icon}</span><span class="agent-cost">${a.cost} credits</span><span class="select-mark" aria-hidden="true">${state.team.includes(a.id)?'✓':'+'}</span></span><h3>${a.name}</h3><p>${a.description}</p></button>`).join('')}</div><div class="bottom-action"><p class="selection-note" role="status">${state.team.length===3?`${STARTING_CREDITS-cost} credits left for the mission.`:'Different teams. Different tradeoffs.'}</p><button class="button dark" data-action="start" ${state.team.length!==3?'disabled':''}>Start mission <span aria-hidden="true">↗</span></button></div><p class="muted" style="font-size:.75rem;margin-top:12px">${MISSION_LENGTH} random scenarios from a bank of ${questionBank.length}. The clock starts when you do.</p></section>${brief()}</div>`;}
function play(){const r=state.questions[state.round],f=state.feedback;root.innerHTML=`<div class="play-top"><span class="eyebrow">LAUNCH READINESS</span><div class="timer mono" role="timer" aria-label="Time remaining"><span aria-hidden="true">◷</span><span id="clock">${time()}</span></div></div><div class="game-layout entry"><section><div class="progress" aria-label="Decision ${state.round+1} of ${state.questions.length}">${state.questions.map((_,i)=>`<span class="${i<=state.round?'done':''}"></span>`).join('')}</div><div class="step-label"><span class="eyebrow">Decision ${String(state.round+1).padStart(2,'0')}</span><span>${String(state.round+1).padStart(2,'0')} / ${String(state.questions.length).padStart(2,'0')}</span></div><div class="stage-title"><h2 id="stage-heading" tabindex="-1">${r.title}</h2><p>${r.description}</p></div>${f?`<div class="feedback ${f.score<15?'warn':''}" role="status"><div class="eyebrow" style="margin-bottom:12px">${r.concept}</div><h3>${f.score>=15?'Good call.':f.score>=8?'A useful tradeoff.':'That had a consequence.'}</h3><p>${f.message}</p><p class="mono" style="margin-top:14px;font-size:.8rem">+${points(f.score,state.questions.length)} judgment points · ${f.cost} credits used</p><button class="button dark" data-action="next">${state.round===state.questions.length-1?'See your debrief':'Next decision'} <span aria-hidden="true">→</span></button></div>`:`<div class="choices">${r.options.map((o,i)=>`<button class="choice" data-choice="${i}"><span class="letter" aria-hidden="true">${'ABC'[i]}</span><span><strong>${o.title}</strong><small>${o.detail}</small></span></button>`).join('')}</div>`}</section><aside class="side play-side"><span class="eyebrow">Live from the workflow</span><div class="event"><strong>FIELD NOTE / ${String(state.round+1).padStart(2,'0')}</strong><p>${r.event}</p></div><div class="objective"><strong>Your team</strong><div class="team-list">${team().map(a=>`<span class="team-member">${a.name}</span>`).join('')}</div></div><div class="metric"><span>Credits remaining</span><strong class="mono">${state.credits}</strong></div><div class="metric"><span>Mission score</span><strong class="mono">${score(state)} / 100</strong></div>${state.credits<0?'<p style="margin-top:15px;color:#f4c097">Budget exceeded. Finish the mission and review the tradeoffs.</p>':''}<p style="margin-top:22px;font-size:.75rem">The timer includes feedback. Read, decide, keep moving.</p></aside></div>`;}
function coachingPanel(advice) {
 return `<section class="coaching" aria-labelledby="focus-heading"><div class="section-head"><h2 id="focus-heading">Your next focus</h2><span class="muted">Based on ${advice.assessedCount} answered decisions</span></div>
 ${advice.focus.length ? `<div class="focus-grid">${advice.focus.map((area,i)=>`<article class="focus-card"><span class="eyebrow">Focus 0${i+1}</span><h3>${esc(area.title)}</h3><p class="focus-evidence"><strong>In your run:</strong> ${esc(area.question.title)} ${esc(area.evidence.message)}</p><p><strong>Why it matters:</strong> ${esc(area.why)}</p><p class="next-step"><strong>Try this next</strong>${esc(area.action)}</p></article>`).join('')}</div>` : `<p class="coaching-empty">${advice.advanced ? 'No major gaps surfaced in your answers. Take the next step with a harder exercise.' : advice.assessedCount ? 'No major gaps surfaced in the decisions you answered. Finish another run to explore more topics.' : 'No decisions were answered, so there is not enough evidence to suggest focus areas. Start another run when you are ready.'}</p>`}
 ${advice.strengths.length ? `<div class="strengths"><h3>Strengths demonstrated</h3><ul>${advice.strengths.map(area=>`<li><strong>${esc(area.title)}</strong><span>${area.answers.length} decision${area.answers.length===1?'':'s'} with sound judgment. Practiced in “${esc(area.question.title)}”</span></li>`).join('')}</ul></div>` : ''}
 ${advice.advanced ? `<article class="advanced"><span class="eyebrow">Advanced practice</span><h3>Turn your judgment into a delivery plan.</h3><p>Choose a real AI workflow. Define its evidence requirements, tool permissions, evaluation gates, and recovery plan. Then ask a colleague to challenge it with a missing source and a failed tool call.</p></article>` : ''}
 ${advice.unanswered.length ? `<div class="unassessed"><h3>Not assessed · ${advice.unanswered.length} unanswered</h3><p>These topics are opportunities to explore, not identified weaknesses.</p><p>${advice.unanswered.map(q=>esc(q.concept)).join(' · ')}</p></div>` : ''}
 </section>`;
}
function results(){const advice=coaching(state);const total=score(state),complete=state.answers.length===state.questions.length;const title=!complete?'Time to regroup.':total>=85?'Ready to lead.':total>=55?'A promising start.':'Good lessons. Next run?';root.innerHTML=`<section class="results entry"><span class="pill">${state.expired?'Time’s up':'Mission complete'} · ${state.answers.length} / ${state.questions.length} decisions</span><div class="result-top"><div class="score-ring"><strong>${total}</strong><small>MISSION / 100</small></div><div><h1 tabindex="-1" id="result-heading">${title}</h1><p class="muted" style="margin-top:12px">${total>=85?'You balanced useful automation with evidence and oversight.':'A strong AI workflow needs clear evidence, bounded access, and a plan for uncertainty.'}</p><p class="mono" style="font-size:.8rem;margin-top:12px">${state.credits>=0?`${state.credits} credits remaining`:`${Math.abs(state.credits)} credits over budget`} · ${time()} left</p></div></div>${coachingPanel(advice)}<p class="muted score-note">Each decision earns up to ${100/state.questions.length} points. Unanswered questions earn no mission points and are not assessed for learning feedback.</p><div class="section-head"><h3>Your decisions, decoded</h3><span class="muted" style="font-size:.8rem">Take these into your next project</span></div><div class="lessons">${state.questions.map((r,i)=>{const a=state.answers.find(a=>a.questionId===r.id);return `<article class="lesson"><div class="lesson-top"><h3>${r.concept}</h3><span class="outcome">${a?`${points(a.score,state.questions.length)} / ${100/state.questions.length}`:'Not assessed'}</span></div><p>${a?esc(a.message):'Unanswered this run. This topic was not used to identify your focus areas.'}</p></article>`;}).join('')}</div><div class="result-actions"><button class="button dark" data-action="replay">Build another team <span aria-hidden="true">↗</span></button></div><p class="muted" style="font-size:.75rem;margin-top:16px">Scores reflect this fictional scenario, not a professional certification. Credits model effort and cost.</p></section>`;}
function render(focus=false){if(state.phase==='setup')setup();else if(state.phase==='playing')play();else results();if(focus){const target=root.querySelector('#stage-heading,#result-heading,h1');if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}}
function act(action,value){if(action==='team'){if(state.phase!=='setup'||!agents.some(a=>a.id===value))return false;const selected=state.team.includes(value);if(!selected&&state.team.length===3){root.querySelector('.selection-note').textContent='Remove a teammate before adding another.';return false;}state.team=selected?state.team.filter(id=>id!==value):[...state.team,value];render();root.querySelector(`[data-agent="${value}"]`)?.focus({preventScroll:true});return true;}if(action==='start'){if(!startGame(state,Date.now()))return false;render(true);return true;}if(action==='choice'){const ok=choose(state,value,Date.now());render();root.querySelector('[data-action="next"]')?.focus({preventScroll:true});return ok;}if(action==='next'){if(!next(state,Date.now()))return false;render(true);return true;}if(action==='replay'){state=createGame();render(true);return true;}return false;}
root.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.agent)act('team',target.dataset.agent);else if(target.dataset.choice!==undefined)act('choice',Number(target.dataset.choice));else act(target.dataset.action);});
function tick(){if(state.phase!=='playing')return;if(!remaining(state,Date.now())){finish(state,true);render(true);return;}const clock=document.querySelector('#clock');if(clock)clock.textContent=time();document.querySelector('.timer')?.classList.toggle('urgent',remaining(state,Date.now())<=30);}
setInterval(tick,250);document.addEventListener('visibilitychange',tick);render();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_mission',description:'Read the current simulated game state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({phase:state.phase,team:[...state.team],round:state.round+1,questionIds:state.questions.map(q=>q.id),questionCount:state.questions.length,bankSize:questionBank.length,secondsLeft:remaining(state,Date.now()),credits:state.credits,score:score(state)})},{name:'choose_mission_option',description:'Choose an option in the current timed game decision, with the same consequences as clicking it.',inputSchema:{type:'object',properties:{option:{type:'integer',minimum:0,maximum:2}},required:['option'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.option)||input.option<0||input.option>2||state.phase!=='playing'||state.feedback)throw new Error('A current unanswered decision and option 0–2 are required.');if(!act('choice',input.option))throw new Error('The mission has expired.');return{feedback:state.feedback,credits:state.credits};}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
